// --- Rotation matrix for pi/3 (60 degrees)
#define rot(a) mat2(cos(1.047*(a) + vec4(0,1.57,-1.57,0)))

// --- Curved line segment distance function (constrained arcs)
float curvedLineDistance(vec2 U, vec2 P, vec2 _P, float density) {
    // Treat the line segment as a constrained circular arc
    vec2 mid = (P + _P) / 2.0; // Midpoint of the line segment
    vec2 dir = normalize(_P - P); // Direction of the line segment
    float curvature = 1.5; // Curvature factor (adjust for more/less curvature)
    vec2 center = mid + vec2(-dir.y, dir.x) * curvature * length(_P - P); // Center of the arc

    // Calculate distance from U to the constrained circular arc
    float radius = length(_P - P) * curvature;
    vec2 toU = U - center;
    float angle = atan(toU.y, toU.x); // Angle of U relative to the arc center
    vec2 arcPoint = center + radius * vec2(cos(angle), sin(angle)); // Closest point on the arc

    // Ensure the arcPoint lies between P and _P
    float t = dot(arcPoint - P, _P - P) / dot(_P - P, _P - P);
    t = clamp(t, 0.0, 1.0); // Constrain t to [0, 1]
    arcPoint = mix(P, _P, t); // Project arcPoint onto the line segment

    return length(U - arcPoint); // Distance to the constrained arc
}

