float p[] = float[](.318, -1., -2., 1., 2., 0., 1.); // Turn angles (multiples of pi/3)
int s[] = int[](1, -1, -1, 1, 1, 1, -1); // Draw direction: forward (1) or reverse (-1)

// --- Macro to define recursive drawing functions
#define Rec(draw, draw2)                                      \
float draw(vec2 U, vec2 P, vec2 _P, float density) {          \
    vec2 D = _P - P;                                          \
    if (length(U - (P + _P) / 2.) > .88 * length(D)) return 9.; \
    float d = 9.;                                             \
    for (int i = 0; i < p.length(); i++) {                    \
        _P = P;                                               \
        D *= rot(p[i]);                                       \
        P += .378 * D;                                        \
        if (density > 0.0) {                                  \
            d = min(d, s[i] > 0 ? draw2(U, _P, P, density - 1.0) : draw2(U, P, _P, density - 1.0)); \
        } else {                                              \
            float dist = s[i] > 0 ? curvedLineDistance(U, _P, P, density) : curvedLineDistance(U, P, _P, density); \
            d = min(d, dist); \
        }                                                     \
    }                                                         \
    return d;                                                 \
}

