// --- Main function
void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy; // Screen resolution
    vec2 U = (2. * u - R) / min(R.x, R.y); // Normalized pixel coordinates (scaled to fit screen)

    // Shift the curve left and up
    float curveRadius = 1.0; // Approximate radius of the curve
    U += vec2(+0.75 * curveRadius, -0.5 * curveRadius); // Shift left and up

    vec2 P = vec2(1.0); // Starting point of the curve (scaled to fit screen)

    // Sample the input texture (iChannel0) for density control and color
    vec3 textureColor = texture(iChannel0, u / R).rgb; // RGB values from the texture

    // Use iMouse.x to scale the grayscale value for density control
    float grayscaleFactor = iMouse.x / R.x; // Normalize mouse x to [0, 1]
    float maskValue = textureColor.r * grayscaleFactor; // Scale grayscale value

    // Use iMouse.y to modulate the RGB values
    float rgbModFactor = iMouse.y / R.y; // Normalize mouse y to [0, 1]
    vec3 modifiedColor = mod(textureColor, rgbModFactor); // Modulate RGB values

    // Apply 16x16 Bayer dithering to the grayscale value
    float bayerThreshold = bayer16x16(u);
    float ditheredMaskValue = step(bayerThreshold, maskValue); // Apply Bayer threshold

    // Mix the original and modified colors based on the dithered grayscale value
    vec3 finalColor = mix(textureColor, modifiedColor, ditheredMaskValue - 0.3);

    // Map mask value to recursion depth (e.g., depth range 0 to 5)
    float depth = mix(0.0, 5.0, maskValue); // Reduced depth range for faster compilation

    // Draw the Gosper curve with variable recursion depth
    float curveDistance = draw1(U, -P, P, depth);

    // Output the result with smoothstep for anti-aliasing and color
    float curveIntensity = smoothstep(3. / min(R.x, R.y), 0., curveDistance); // Use curveDistance directly

    // --- Time-based modulation for color cycling
    float timeCycle = sin(iTime * (2.0 * 3.14159 / 6.0)); // Sine wave with 6-second period
    float colorMix = (timeCycle + 1.0) * 0.5; // Map sine wave from [-1, 1] to [0, 1]

    // Interpolate between white and the final color based on the time cycle
    vec3 curveColor = mix(vec3(1.0), finalColor, colorMix); // Plain white when colorMix = 0, colored when colorMix = 1

    // Output the final color with the curve intensity
    O = vec4(curveColor * curveIntensity, 1.0); // Apply modulated color to the curve
}
